export function currentRole(){ try{ const id=localStorage.getItem("salis-role"); return (id&&ROLES.some(r=>r.id===id))?id:"owner"; }catch(e){ return "owner"; } }
export function roleMeta(id){ return ROLES.find(r=>r.id===(id||currentRole()))||ROLES[0]; }
export function can(mod,action,role){
  const r=role||currentRole();
  const g=(PERMS[mod]||{})[r]||"";
  return g.includes(action);
}
export function canScreen(screen,role){
  const mod=SCREEN_MODULE[screen];
  if(!mod) return true;               // reference/spec screens are open
  return can(mod,"v",role);
}
export function navFor(nav,role){
  const r=role||currentRole();
  return nav.map(g=>({...g,items:(g.items||[]).filter(it=>{
    const key=(it.href||"").replace(".dc.html","").replace(".Mobile","");
    const mod=SCREEN_MODULE[key];
    return !mod || can(mod,"v",r);
  })})).filter(g=>g.items.length);
}
export function fieldHidden(field,role){
  const r=role||currentRole();
  const rule=FIELD_RULES.find(f=>f.field===field);
  return !!rule && rule.hidden.includes(r);
}
export function approvalLimit(role){ return roleMeta(role).limit; }


